const x = dist.normal({ mean: 4, sd: 1 });
const cell = [{ mean: 4, sd: 1 }];
const drawn = sample(cell, { n: Infinity });
const dots = sample(cell, { n: 100, at: "quantiles" });
// one row per geom
spread({ dir: "y", spacing: 8 }, [
  // halfeye
  chart(cell).mark(layer([slab(x), interval(x)])),
  // eye
  chart(cell).mark(
    layer([
      slab(x, { side: "both" }),
      // gap: this should sit on the slab's zero line, but a
      // layer aligns its children's boxes, not their
      // origins
      interval(x),
    ])
  ),
  // gradientinterval: opacity from the density, scaled so
  // the peak is 1
  chart(cell).mark(
    layer([gradientinterval(x), interval(x)])
  ),
  // ccdfinterval: one bar per level, from the axis start to
  // the draw
  layer([
    chart(drawn)
      .flow(spread({ by: "level", dir: "y", spacing: 0 }))
      .mark(
        rect({
          dims: { x: { min: 0, max: x } },
          fill: SLAB,
        })
      ),
    chart(cell).mark(interval(x)),
  ]),
  // cdfinterval: one bar per level, from the draw to the
  // axis end
  layer([
    chart(drawn)
      .flow(spread({ by: "level", dir: "y", spacing: 0 }))
      .mark(
        rect({
          dims: { x: { min: x, max: 8 } },
          fill: SLAB,
        })
      ),
    chart(cell).mark(interval(x)),
  ]),
  // interval
  chart(cell).mark(
    interval(x, {
      levels: [0.95, 0.8, 0.5],
      point: false,
      h: 10,
      opacity: 1 / 3,
    })
  ),
  // pointinterval
  chart(cell).mark(interval(x)),
  // slab
  chart(cell).mark(slab(x)),
  // histinterval
  layer([
    chart(histDf)
      .flow(
        partition({
          by: field("x").bin(Bin.thresholds(30)),
          dir: "x",
        })
      )
      .mark(rect({ h: field("x").count(), fill: SLAB })),
    chart(cell).mark(interval(x)),
  ]),
  // dots
  chart(dots)
    .flow(
      partition({ by: x.bin(Bin.step(0.1)), dir: "x" }), // chosen by hand; ggdist picks the width so the tallest stack fits
      stack({ dir: "y" })
    )
    .mark(circle({ r: 2 })),
  // dotsinterval
  layer([
    chart(dots)
      .flow(
        partition({ by: x.bin(Bin.step(0.1)), dir: "x" }), // chosen by hand; ggdist picks the width so the tallest stack fits
        stack({ dir: "y" })
      )
      .mark(circle({ r: 2 })),
    chart(cell).mark(interval(x)),
  ]),
]);

